  qty+=record.qty;if(record.jobNo&&record.jobNo!=='MANUAL_MODE')jobs.add(record.jobNo);const hour=Number(record.time?.slice(0,2));if(Number.isInteger(hour)&&hour>=0&&hour<24)hours[hour]+=record.qty;
