document.addEventListener('click',e=>{const target=e.target.closest('[data-action],[data-detail],[data-month],[data-reference],[data-edit-initiative],[data-delete-initiative]');if(!target)return;const d=target.dataset;if(d.detail!==undefined){state.detail=d.detail==='true';render();}if(d.month!==undefined){state.period=d.month;render();}if(d.reference)reference(d.reference);if(d.editInitiative!==undefined)initiativeForm(Number(d.editInitiative));if(d.deleteInitiative!==undefined){const i=Number(d.deleteInitiative),title=state.initiatives[i].title;openDialog('ลบแผนงาน',`<p>ลบแผนงาน “${escapeHTML(title)}” จาก Google Sheets</p><div class="dialog-actions"><button class="button secondary" data-action="close-dialog">ยกเลิก</button><button class="button primary" data-action="confirm-delete" data-index="${i}">ลบแผนงาน</button></div>`);}switch(d.action){case 'unpriced-breakdown':openDialog('รายการที่ไม่รวมในรายได้',unpricedBreakdownHTML());break;case 'unpriced-sources':$('#dialog').close();location.hash='sources';break;case 'export-pl':exportCSV('pl');break;case 'toggle-expand':{const cards=$$('#view .panel, #view .kpi'),i=cards.indexOf(target.closest('.panel, .kpi'));state.expanded=state.expanded===i?null:i;applyExpanded();break;}case 'sources':location.hash='sources';break;case 'create-input':target.disabled=true;window.PL_DB.createInputSheet(D.year,d.dept||'').then(title=>{toast(`สร้างแท็บ ${title} แล้ว`);return refreshFromSheet(d.dept?'d:'+d.dept.toLowerCase():'pd').catch(e=>toast('สร้างแท็บแล้ว แต่โหลดข้อมูลใหม่ไม่สำเร็จ ลองรีเฟรชหน้า: '+(e.message||'')));}).catch(error=>{target.disabled=false;toast('สร้างแท็บไม่สำเร็จ: '+(error.message||'ตรวจสิทธิ์ Editor'));});break;case 'edit-production-fx':exchangeRateForm();break;case 'model-price-notes':openDialog('หมายเหตุราคา · '+d.model,modelPriceNotes(d.model));break;case 'production-rules':openDialog('หมายเหตุการคำนวณ',productionRulesHTML);break;case 'reset-production-fx':fxOverride=null;resetPrices();try{localStorage.removeItem(fxStorageKey);}catch(e){}$('#dialog').close();render();toast('ใช้อัตราจาก Sale Price!O1 แล้ว');break;case 'retry-job-order':D.jobOrder={status:'not-loaded',records:[],rowCount:0};render();break;case 'save-plan':if(persist())$('#save-state').textContent=saveLabel();break;case 'reset-plan':state.assumptions={...defaults};state.dirty=true;render();toast('คืนสมมติฐานเป็น Forecast ต้นทางแล้ว');break;case 'add-initiative':initiativeForm();break;case 'close-dialog':$('#dialog').close();break;case 'confirm-delete':state.initiatives.splice(Number(d.index),1);persist();$('#dialog').close();render();toast('ลบแผนงานแล้ว');break;}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='source-search'){$('#source-rows').innerHTML=sourceRows(el.value);return;}const key=el.dataset.driver||el.dataset.slider;if(!key)return;let v=Number(el.value);if(el.value.trim()===''||!Number.isFinite(v)||v<Number(el.min)||v>Number(el.max)){el.setCustomValidity('ระบุตัวเลขระหว่าง '+el.min+' ถึง '+el.max);el.reportValidity();return;}el.setCustomValidity('');state.assumptions[key]=v;state.dirty=true;const paired=$(el.dataset.driver?`[data-slider="${key}"]`:`[data-driver="${key}"]`);paired.value=v;$('#plan-results').innerHTML=planResults();icons($('#plan-results'));$('#save-state').textContent=saveLabel();});
document.addEventListener('change',e=>{if(e.target.id==='daily-chart-granularity'){if(dailyChartModes.some(([value])=>value===e.target.value))state.chartGranularity=e.target.value;render();return;}const key=e.target.dataset.driver;if(key&&e.target.validationMessage){e.target.value=state.assumptions[key];e.target.setCustomValidity('');}});
document.addEventListener('submit',e=>{if(e.target.id==='department-form'){e.preventDefault();const name=String(new FormData(e.target).get('name')||'').trim(),button=e.target.querySelector('[type=submit]');if(!name)return;if(D.scopes.some(x=>x.label.toLowerCase()===(/^แผนก/.test(name)?name:'แผนก '+name).toLowerCase())){toast('มีแผนกชื่อนี้อยู่แล้ว');return;}button.disabled=true;window.PL_DB.createInputSheet(D.year,name).then(title=>{$('#dialog').close();toast(`สร้างแท็บ ${title} แล้ว`);return refreshFromSheet('d:'+name.toLowerCase()).catch(e=>toast('สร้างแท็บแล้ว แต่โหลดข้อมูลใหม่ไม่สำเร็จ ลองรีเฟรชหน้า: '+(e.message||'')));}).catch(error=>{button.disabled=false;toast('เพิ่มแผนกไม่สำเร็จ: '+(error.message||'ตรวจสิทธิ์ Editor'));});return;}if(e.target.id==='exchange-rate-form'){e.preventDefault();const value=Number(new FormData(e.target).get('rate'));if(!Number.isFinite(value)||value<=0){toast('ระบุอัตราแลกเปลี่ยนมากกว่า 0');return;}fxOverride=value;resetPrices();let stored=true;try{localStorage.setItem(fxStorageKey,String(value));}catch(error){stored=false;}$('#dialog').close();render();toast(stored?'คำนวณใหม่และจำอัตราไว้ในเบราว์เซอร์แล้ว':'คำนวณใหม่แล้ว แต่เบราว์เซอร์ไม่สามารถจำค่าได้');return;}if(e.target.id!=='initiative-form')return;e.preventDefault();const form=e.target,f=new FormData(form),a=Object.fromEntries(f.entries());a.title=a.title.trim();a.owner=a.owner.trim();if(!a.title||!a.owner){toast('กรอกชื่อแผนงานและผู้รับผิดชอบ');return;}const i=form.dataset.index;if(i==='')state.initiatives.push(a);else state.initiatives[Number(i)]=a;persist();$('#dialog').close();render();});
function route(){state.expanded=null;const p=location.hash.slice(1)||'overview';state.page=pageMeta[p]?p:'overview';$('#sidebar').classList.remove('open');render();}
window.addEventListener('hashchange',route);route();

populateScopes();
$('#year').innerHTML=`<option>${D.year}</option>`;
$('.page-footer').innerHTML=`<span><i></i>ข้อมูลจาก Google Sheets · ปี ${D.year}</span><span>อ่านล่าสุด ${new Date(D.loadedAt||Date.now()).toLocaleString('th-TH')}</span>`;
$('#add-department').addEventListener('click',()=>openDialog('เพิ่มแผนก',`<form id="department-form"><p>สร้างแท็บ <code>PL Input ${D.year} ชื่อแผนก</code> ใน Google Sheets พร้อมหัวตารางรายการแบบ BP บริษัท A ผู้กดต้องมีสิทธิ์ Editor แผนกที่ไม่ใช่ H9 กรอกรายได้ Actual เอง เพราะ barcode record เป็นข้อมูลของ H9</p><div class="form-field"><label for="department-name">ชื่อแผนก</label><input id="department-name" name="name" required maxlength="60" autocomplete="off" placeholder="เช่น QA"></div><div class="dialog-actions"><button class="button secondary" type="button" data-action="close-dialog">ยกเลิก</button><button class="button primary" type="submit">สร้างแผนก</button></div></form>`));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.expanded!==null&&!$('#dialog').open){state.expanded=null;applyExpanded();}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(fitCharts,120);});
